"use client";

import { motion } from "framer-motion";
import { Mail, Phone, MapPin, ArrowRight } from "lucide-react";
import { Footer } from "@/components/Footer";
import { GradientText } from "@/components/ui/GradientText";

export default function ContactPage() {
  return (
    <div className="bg-neutral-950 min-h-screen w-full text-white font-sans selection:bg-neutral-800 selection:text-white flex flex-col">
      <main className="flex-1 flex items-center justify-center pt-24 pb-12 px-4 md:px-8">
        
        <div className="max-w-7xl w-full mx-auto">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-16 items-center">
                
                {/* Left Column: Contact Details */}
                <div className="flex flex-col justify-center">
                    <motion.span 
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.1 }}
                        className="text-xs md:text-sm font-bold tracking-widest uppercase text-neutral-500 mb-4 block"
                    >
                        Connect
                    </motion.span>
                    
                    <GradientText
                        words="Get in touch"
                        className="text-4xl md:text-5xl lg:text-6xl text-white mb-6"
                        as="h1" // Semantic h1 for page title
                    />

                    <motion.p
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.3 }}
                        className="text-lg text-neutral-400 mb-10 max-w-lg"
                    >
                        Let's talk about your growth strategy.
                    </motion.p>

                    <div className="space-y-8">
                        {/* Email */}
                        <motion.div 
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: 0.4 }}
                            className="group"
                        >
                            <div className="flex items-center gap-3 mb-1 text-neutral-500 group-hover:text-white transition-colors">
                                <Mail className="w-5 h-5" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">Email</h3>
                            <a href="mailto:hello@admanics.com" className="text-base font-medium text-neutral-300 hover:text-white transition-all">
                                hello@admanics.com
                            </a>
                        </motion.div>

                        {/* Phone */}
                        <motion.div 
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: 0.5 }}
                            className="group"
                        >
                            <div className="flex items-center gap-3 mb-1 text-neutral-500 group-hover:text-white transition-colors">
                                <Phone className="w-5 h-5" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">Phone</h3>
                            <a href="tel:+18442362642" className="text-base font-medium text-neutral-300 hover:text-white transition-all">
                                +1 (844) 236-2642
                            </a>
                        </motion.div>

                        {/* Office */}
                        <motion.div 
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: 0.6 }}
                            className="group"
                        >
                            <div className="flex items-center gap-3 mb-1 text-neutral-500 group-hover:text-white transition-colors">
                                <MapPin className="w-5 h-5" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">Office</h3>
                            <p className="text-base text-neutral-300 mb-2">
                                Sydney, NSW 2000, Australia
                            </p>
                            <a href="https://maps.google.com" target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 text-xs font-bold text-white hover:text-neutral-300 transition-colors uppercase tracking-wider">
                                Get directions <ArrowRight className="w-3 h-3 ml-1" />
                            </a>
                        </motion.div>
                    </div>
                </div>

                {/* Right Column: Image */}
                <motion.div 
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: 0.2, duration: 0.8, ease: "circOut" }}
                    className="h-[50vh] lg:h-[80vh] w-full rounded-3xl overflow-hidden relative"
                >
                    <div className="absolute inset-0 bg-neutral-900 animate-pulse" />
                    <img 
                        src="https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?q=80&w=2670&auto=format&fit=crop"
                        alt="Admanics Office Building" 
                        className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-1000"
                    />
                </motion.div>

            </div>
        </div>

      </main>
      <Footer />
    </div>
  );
}

"use client";

import { motion } from "framer-motion";
import { Button } from "@/components/ui/Button";
import { GradientText } from "@/components/ui/GradientText";

export function AboutSection() {
  return (
    <section id="about" className="bg-neutral-950 py-24 px-4 font-sans text-white">
      <div className="max-w-7xl mx-auto flex flex-col items-end text-right gap-8 px-4 md:px-8">
        <motion.span 
            initial={{ opacity: 0, y: 10 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-sm font-bold tracking-widest uppercase text-neutral-500 mb-4 block"
        >
          About
        </motion.span>

        {/* Replaced with verified GradientText component */}
        <GradientText 
            words="AI-Powered Growth Systems Built to Scale"
            className="text-3xl md:text-4xl lg:text-5xl max-w-4xl"
        />

        {/* Description Text */}
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 0.2 }}
            className="max-w-3xl"
        >
            <p className="text-lg md:text-xl text-neutral-400 leading-relaxed">
              Admanics is an AI marketing and technology agency that builds automated, scalable growth systems for businesses operating in global markets.
               We help companies replace fragmented marketing and manual processes with structured, performance-driven workflows that connect advertising, websites, CRM, and sales operations into a single system.

By combining performance marketing, ecommerce growth, web development, content, social media, and AI-powered automation using tools like Zoho and Zapier, we ensure every lead is tracked, nurtured, and converted efficiently.

Admanics focuses on building long-term growth infrastructure—not short-term campaigns—so businesses can scale predictably, operate efficiently, and grow without operational chaos.
            </p>
        </motion.div>
      </div>
    </section>
  );
}

"use client";

import { Button } from "@/components/ui/Button";
import { motion } from "framer-motion";
import { GradientText } from "@/components/ui/GradientText";

const faqs = [
  {
    question: "How does automation work?",
    answer: "We build custom workflows that connect your advertising, website, CRM, and sales tools into one system. When a lead arrives, it's automatically tracked, nurtured, and passed to sales without manual handoffs. The system learns and optimizes itself over time.",
  },
  {
    question: "What tools do you integrate?",
    answer: "We work with Zoho CRM, Zapier, Google Ads, Facebook Ads, Shopify, and most major platforms. If your tool has an API, we can connect it. We assess your existing stack and build workflows that fit your specific needs.",
  },
  {
    question: "How long until we see results?",
    answer: "Most clients see measurable improvements within four to six weeks. The first phase focuses on data collection and system setup. Once workflows are live, optimization happens continuously based on real performance data.",
  },
  {
    question: "Do you handle ongoing support?",
    answer: "Yes. We provide continuous monitoring, optimization, and support. Your system evolves as your business grows. We track performance, identify bottlenecks, and refine workflows to keep your growth predictable and efficient.",
  },
  {
    question: "What about data security?",
    answer: "Data security is non-negotiable. We follow industry standards for encryption, access control, and compliance. All integrations use secure APIs, and your data remains in your own systems. We never store sensitive information unnecessarily.",
  },
];

export function FAQ() {
  return (
    <section id="faq" className="bg-neutral-950 py-24 px-4 font-sans text-white">
      <div className="max-w-4xl mx-auto px-4 md:px-8">
        
        {/* Header - Center Aligned */}
        <div className="max-w-3xl mb-16 mx-auto text-center">
            <GradientText 
                words="Questions"
                className="text-3xl md:text-4xl lg:text-5xl mb-6"
            />
          <motion.p
            initial={{ opacity: 0, y: 10 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-lg text-neutral-400"
          >
            Everything you need to know about automated growth systems
          </motion.p>
        </div>

        {/* Q&A List */}
        <div className="space-y-6 mb-24">
            {faqs.map((faq, idx) => (
                <motion.div
                    key={idx}
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                    transition={{ delay: idx * 0.1 }}
                    className="flex flex-col gap-3 p-6 rounded-lg border border-white/10 bg-white/5 backdrop-blur-sm transition-colors hover:bg-white/10"
                >
                    <h3 className="text-xl font-bold text-white">{faq.question}</h3>
                    <p className="text-neutral-400 leading-relaxed text-base">{faq.answer}</p>
                </motion.div>
            ))}
        </div>

        {/* Footer actions - Still have questions? */}
        <motion.div 
            id="ready"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 0.2 }}
            className="text-center"
        >
            <h3 className="text-3xl md:text-4xl font-bold text-white mb-4">Still have questions?</h3>
            <p className="text-neutral-400 mb-8 max-w-xl mx-auto">
                Reach out and let's talk about your growth
            </p>
            <a href="/contact">
                <Button className="bg-neutral-100 text-black hover:bg-white rounded-lg px-10 py-4 text-lg font-bold shadow-[0_0_20px_rgba(255,255,255,0.1)] transition-all cursor-pointer">
                    Contact
                </Button>
            </a>
        </motion.div>

      </div>
    </section>
  );
}

"use client";

import { Facebook, Instagram, Linkedin, Twitter, Youtube } from "lucide-react";

